import{_ as a,C as o,c as e,o as i,j as r,b as t,a0 as s,a as n,w as l,G as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const p=JSON.parse('{"title":"Campo de Treinamento: Guia de Fim de Semana","description":"","frontmatter":{},"headers":[],"relativePath":"pt/training-camp.md","filePath":"pt/training-camp.md"}');const c=a({name:"pt/training-camp.md"},[["render",function(a,p,c,m,g,h){const f=o("Mermaid");return i(),e("div",null,[p[2]||(p[2]=r("h1",{id:"campo-de-treinamento-guia-de-fim-de-semana",tabindex:"-1"},[n("Campo de Treinamento: Guia de Fim de Semana "),r("a",{class:"header-anchor",href:"#campo-de-treinamento-guia-de-fim-de-semana","aria-label":'Permalink to "Campo de Treinamento: Guia de Fim de Semana"'},"​")],-1)),p[3]||(p[3]=r("p",null,"Como organizar um campo de treinamento de fim de semana para 10 a 20 jogadores",-1)),p[4]||(p[4]=r("p",null,"Este guia completo ajuda você a organizar e conduzir um acampamento de treinamento de fim de semana que combina teoria, prática e competição. Combine o conteúdo sobre o aspecto mental do esqui, disponível neste site, com a aplicação prática nas pistas para obter o máximo impacto.",-1)),p[5]||(p[5]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"A filosofia do campo de treinamento"),r("p",null,[r("strong",null,"Teoria sem prática é apenas informação. Prática sem teoria é apenas repetição. Competição sem reflexão é apenas brincadeira."),n(" Este fim de semana integra os três para uma aprendizagem transformadora.")])],-1)),(i(),t(u,null,{default:l(()=>[d(f,{id:"mermaid-14",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWeekend%20Camp%5D%20--%3E%20B%5BFriday%3A%20Theory%5D%0A%20%20%20%20B%20--%3E%20C%5BSaturday%3A%20Practice%5D%0A%20%20%20%20C%20--%3E%20D%5BSunday%3A%20Competition%5D%0A%20%20%20%20D%20--%3E%20E%5BIntegration%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:l(()=>[...p[0]||(p[0]=[n(" Loading... ",-1)])]),_:1})),p[6]||(p[6]=s('<h2 id="planejamento-pre-acampamento" tabindex="-1">Planejamento Pré-Acampamento <a class="header-anchor" href="#planejamento-pre-acampamento" aria-label="Permalink to &quot;Planejamento Pré-Acampamento&quot;">​</a></h2><h3 id="tamanho-e-estrutura-do-grupo" tabindex="-1">Tamanho e estrutura do grupo <a class="header-anchor" href="#tamanho-e-estrutura-do-grupo" aria-label="Permalink to &quot;Tamanho e estrutura do grupo&quot;">​</a></h3><p><strong>Ideal para:</strong> 10-20 jogadores</p><ul><li><strong>Acampamento pequeno (10-12):</strong> Compartilhamento mais íntimo e profundo</li><li><strong>Acampamento grande (16-20):</strong> Perspectivas mais diversas, requer subgrupos</li></ul><p><strong>Estrutura da Equipe:</strong></p><ul><li>Dividam-se em equipes de 3 a 4 pessoas para treino e competição.</li><li>Misture níveis de habilidade e estilos de jogo.</li><li>Rotacionar as equipes ao longo do fim de semana</li></ul><h3 id="requisitos-de-pessoal" tabindex="-1">Requisitos de pessoal <a class="header-anchor" href="#requisitos-de-pessoal" aria-label="Permalink to &quot;Requisitos de pessoal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Função</th><th>Responsabilidades</th><th>Quantidade</th></tr></thead><tbody><tr><td><strong>Coordenador de Desempenho Mental</strong></td><td>Facilitar sessões teóricas e dinâmicas de grupo</td><td>1</td></tr><tr><td><strong>Treinador Técnico</strong></td><td>Supervisionar os treinos, fornecer feedback</td><td>1-2</td></tr><tr><td><strong>Diretor de Competição</strong></td><td>Organizar torneio, gerenciar logística</td><td>1</td></tr><tr><td><strong>Equipe de Apoio</strong></td><td>Refeições, preparação, administração</td><td>1-2</td></tr></tbody></table><h3 id="requisitos-de-localizacao" tabindex="-1">Requisitos de localização <a class="header-anchor" href="#requisitos-de-localizacao" aria-label="Permalink to &quot;Requisitos de localização&quot;">​</a></h3><p>::: Informações sobre as necessidades da instalação <strong>Pista:</strong></p><ul><li>Vários terrenos (mínimo 3-4 pistas)</li><li>Diferentes tipos de superfície, se possível (cascalho, areia, piso duro) Iluminação para brincadeiras noturnas</li></ul><p><strong>Espaço interno:</strong></p><ul><li>Espaço para 20 pessoas em círculo (sessões teóricas)</li><li>Separado da pista</li><li>Quadro branco/projetor</li><li>Assentos confortáveis</li></ul><p><strong>Alojamento:</strong></p><ul><li>No local ou nas proximidades (a uma curta distância a pé)</li><li>Quartos compartilhados incentivam a criação de laços.</li><li>Espaço tranquilo para reflexão</li></ul><p><strong>Serviço de catering:</strong></p><ul><li>Refeições com foco em nutrição (consulte o <a href="./food">Guia Alimentar</a>)</li><li>Evite quedas bruscas de açúcar</li><li>Postos de hidratação :::</li></ul><p>Lista de Materiais</p><details class="details custom-block"><summary>Lista completa de materiais</summary><p><strong>Sessões teóricas:</strong></p><ul><li>[ ] Cadeiras para círculo (sem mesas)</li><li>[] Bocha e cochonnet para o centro</li><li>[ ] Flip charts e marcadores</li><li>[ ] Notas adesivas</li><li>[ ] Planilhas (Manual do Usuário, Crítico Interior, etc.)</li><li>[ ] Papel e canetas</li><li>[ ] Projetor (para conteúdo do site)</li></ul><p><strong>Sessões de prática:</strong></p><ul><li>[ ] Fita métrica</li><li>[ ] Cones/marcadores para exercícios</li><li>[ ] Câmera de vídeo/tripé</li><li>[ ] Prancheta e papel (rastreamento)</li><li>[ ] Assobiar</li></ul><p><strong>Concorrência:</strong></p><ul><li>[ ] Folhas de pontuação</li><li>[ ] Chaveamento do torneio</li><li>[ ] Prêmios/reconhecimento</li><li>[ ] Kit de primeiros socorros</li></ul><p><strong>Logística:</strong></p><ul><li>[ ] Etiquetas de identificação</li><li>[ ] Lista de participantes com contatos</li><li>[ ] Informações de contato de emergência</li><li>[ ] Garrafas de água</li><li>[ ] Protetor solar</li><li>[ ] Lenços de papel (para trabalho emocional!)</li></ul></details><h2 id="programacao-do-fim-de-semana" tabindex="-1">Programação do fim de semana <a class="header-anchor" href="#programacao-do-fim-de-semana" aria-label="Permalink to &quot;Programação do fim de semana&quot;">​</a></h2><h3 id="sexta-feira-a-noite-3-horas" tabindex="-1">Sexta-feira à noite (3 horas) <a class="header-anchor" href="#sexta-feira-a-noite-3-horas" aria-label="Permalink to &quot;Sexta-feira à noite (3 horas)&quot;">​</a></h3><p><strong>18:00-18:30 - Chegada e boas-vindas</strong></p><ul><li>Check-in</li><li>Atribuição de quartos</li><li>Visão geral do fim de semana</li></ul><p><strong>18:30-19:30 - Jantar</strong></p><ul><li>Refeição com foco em nutrição</li><li>Apresentações informais</li></ul><p><strong>19:30-22:30 - Sessão Teórica: Fundamentos</strong></p><p>Utilize o <a href="./workshop">Guia do Workshop</a> para obter instruções detalhadas sobre a facilitação:</p><ol><li><strong>Regras Básicas (15 min)</strong> - Estabelecer segurança psicológica</li><li><strong>Matriz de Check-in (20 min)</strong> - Avaliar a energia do grupo</li><li><strong>O Iceberg (30 min)</strong> - Explore os pensamentos mais íntimos</li><li><strong>Manual do Usuário (45 min)</strong> - Desenvolver o entendimento da equipe</li><li><strong>Medo em um Chapéu (45 min)</strong> - Quebre o isolamento</li><li><strong>Finalização da compra (15 min)</strong> - Feche o ciclo</li></ol><p><strong>22:30 - Tempo Livre</strong></p><ul><li>Socialização informal</li><li>Descanso e reflexão</li></ul>',30)),(i(),t(u,null,{default:l(()=>[d(f,{id:"mermaid-432",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFriday%20Theory%5D%20--%3E%20B%5BPsychological%20Safety%5D%0A%20%20%20%20B%20--%3E%20C%5BSelf-Awareness%5D%0A%20%20%20%20C%20--%3E%20D%5BTeam%20Understanding%5D%0A%20%20%20%20D%20--%3E%20E%5BReady%20for%20Practice%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A"})]),fallback:l(()=>[...p[1]||(p[1]=[n(" Loading... ",-1)])]),_:1})),p[7]||(p[7]=s('<h3 id="sabado-dia-inteiro-teoria-pratica" tabindex="-1">Sábado (Dia inteiro - Teoria + Prática) <a class="header-anchor" href="#sabado-dia-inteiro-teoria-pratica" aria-label="Permalink to &quot;Sábado (Dia inteiro - Teoria + Prática)&quot;">​</a></h3><p><strong>08:00-09:00 - Café da Manhã e Mindfulness</strong></p><ul><li>Café da manhã tranquilo</li><li>Meditação guiada opcional de 15 minutos</li><li>Defina suas intenções para o dia</li></ul><p><strong>09:00-10:30 - Sessão Teórica: Conectando Conteúdo à Experiência</strong></p><p>Escolha de 3 a 4 tópicos do site da Academia e explore o jogo interior:</p><p><strong>Exemplos de tópicos:</strong></p><ol><li><p><strong><a href="./education/nutrition/">Nutrição</a></strong> (20 min)</p><ul><li>&quot;Como suas escolhas alimentares mudam sob pressão?&quot; — &quot;Você come o que seu corpo precisa ou o que sua ansiedade deseja?&quot;</li><li>Prática: Planeje a nutrição para o dia da competição</li></ul></li><li><p><strong><a href="./education/mental-strength/">Força Mental</a></strong> (25 min) — Qual é a sua relação com o fracasso? — &quot;Como você conversa consigo mesmo depois de errar um golpe?&quot;</p><ul><li>Atividade: Reformule o crítico interno para treinador interno</li></ul></li><li><p><strong><a href="./education/mindfulness/">Mindfulness</a></strong> (25 min) — &quot;Para onde vai sua mente durante a pausa antes do arremesso?&quot; — O que te tira do momento presente?</p><ul><li>Prática: escaneamento corporal de 5 minutos</li></ul></li><li><p><strong><a href="./education/tactics/">Táticas</a></strong> (20 min) — &quot;Sua escolha de arremesso é baseada em estratégia ou medo?&quot;</p><ul><li>&quot;Quando é melhor jogar pelo seguro e quando é melhor arriscar?&quot;</li><li>Discussão: Perfis de risco no grupo</li></ul></li></ol><p><strong>10:30-10:45 - Intervalo</strong></p><p><strong>10:45-12:30 - Integração na pista: Exercícios com foco mental</strong></p><p><strong>Exercício 1: Faça sua previsão (30 min)</strong></p><p>Do <a href="./workshop">Guia do Workshop</a> - pratique assumir a responsabilidade pela intenção e pela dúvida:</p><ol><li>Anuncie o alvo: &quot;Vou atirar no ferro&quot;</li><li>Afirme seu nível de confiança: &quot;Eu sou 7 de 10&quot;</li><li>Nomeie o pensamento interno: &quot;Minha voz interior está preocupada com o efeito reverso&quot;</li><li>Execute o golpe</li><li>Reflita: &quot;O que aconteceu? O que você aprendeu?&quot;</li></ol><p><strong>Exercício 2: Interferência Cognitiva (30 min)</strong></p><p>Teste se a técnica se tornou automática:</p><ul><li>O coordenador faz perguntas complexas enquanto o jogador chuta.</li><li>&quot;Nomeie 5 capitais&quot; ou &quot;Conte de trás para frente a partir de 100, de 7 em 7&quot;</li><li>Sucesso = a técnica é implícita, não processada conscientemente.</li></ul><p><strong>Exercício 3: Prática com o Manual do Usuário (30 min)</strong></p><p>Aplique os Manuais do Usuário de sexta-feira:</p><ul><li>Jogar em equipes de 3 Após cada disparo, os companheiros de equipe respondem de acordo com o Manual do Usuário. — &quot;Marc precisa de silêncio após um erro&quot; — a equipe o homenageia por isso.</li><li>Debriefing: &quot;Como foi se sentir compreendido?&quot;</li></ul><p><strong>12:30-14:00 - Almoço e Descanso</strong></p><ul><li>Refeição com foco em nutrição</li><li>Momento de silêncio para reflexão</li><li>Opcional: Reuniões individuais com o coordenador</li></ul><p><strong>14:00-17:00 - Sessão prática: Adaptação ao terreno</strong></p><p><strong>Objetivo:</strong> Desenvolver adaptabilidade e flexibilidade mental</p><p><strong>Configurar:</strong></p><ul><li>Gire por 3-4 terrenos/pistas diferentes</li><li>45 minutos por terreno</li><li>Foque na adaptação mental, não apenas na técnica.</li></ul><p><strong>Estrutura de Rotação:</strong></p><table tabindex="0"><thead><tr><th>Terreno</th><th>Foco Mental</th><th>Prática</th></tr></thead><tbody><tr><td><strong>Terreno 1: Macio/Areia</strong></td><td>Aceitação da incerteza</td><td>&quot;O dado - aceite o que é&quot;</td></tr><tr><td><strong>Terreno 2: Duro/Cascalho</strong></td><td>Precisão sob pressão</td><td>&quot;Confie na sua técnica&quot;</td></tr><tr><td><strong>Terreno 3: Irregular</strong></td><td>Regulação emocional</td><td>&quot;Mantenha a calma quando for injusto&quot;</td></tr><tr><td><strong>Terreno 4: Competição</strong></td><td>Acesso ao estado de fluxo</td><td>&quot;Encontre a zona&quot;</td></tr></tbody></table><p><strong>Facilitação:</strong></p><ul><li>O treinador técnico fornece feedback sobre a técnica.</li><li>O MPC pergunta: &quot;O que está passando pela sua cabeça agora?&quot;</li><li>Diário dos jogadores entre as rotações</li></ul><p><strong>17:00-18:00 - Intervalo e Reflexão</strong></p><ul><li>Diário individual — O que você aprendeu sobre si mesmo hoje? — &quot;O que você fará de diferente amanhã?&quot;</li></ul><p><strong>18:00-19:00 - Jantar</strong></p><p><strong>19:00-21:00 - Teoria Noturna: Vulnerabilidade Profunda</strong></p><p><strong>Atividade 1: Reinterpretando o Crítico Interior (45 min)</strong></p><p>Consulte o <a href="./workshop">Guia do Workshop</a> para obter o protocolo completo:</p><ol><li>Identifique a frase exata do crítico.</li><li>Reformule como Coach Interior</li><li>Prática em parceria</li></ol><p><strong>Atividade 2: Preparação para a Competição (45 min)</strong></p><p>Amanhã é dia de competição. Prepare-se mentalmente:</p><ol><li><p><strong>Visualização (15 min)</strong></p><ul><li>Feche os olhos Imagine a foto perfeita Sinta a confiança</li><li>Observe a calma</li></ul></li><li><p><strong>Protocolos de Equipe (20 min)</strong></p><ul><li>Criar sinais de apoio</li><li>&quot;Preciso de uma reinicialização&quot; = toque nas bolas</li><li>&quot;Preciso de incentivo&quot; = cumprimento com o punho.</li><li>&quot;Preciso de espaço&quot; = recuar</li></ul></li><li><p><strong>Definir intenções (10 min)</strong> — &quot;Amanhã, vou me concentrar em...&quot; — &quot;Meu objetivo não é vencer, mas sim...&quot; — &quot;Vou praticar...&quot;</p></li></ol><p><strong>Check-out (30 min)</strong> Compartilhe um medo sobre o amanhã.</p><ul><li>Compartilhe uma intenção</li><li>Apoio em grupo</li></ul><p><strong>21:00 - Tempo Livre</strong></p><ul><li>Ir para a cama cedo (competição amanhã!)</li><li>Reflexão silenciosa</li></ul><h3 id="domingo-dia-da-competicao" tabindex="-1">Domingo (Dia da Competição) <a class="header-anchor" href="#domingo-dia-da-competicao" aria-label="Permalink to &quot;Domingo (Dia da Competição)&quot;">​</a></h3><p><strong>08:00-09:00 - Café da manhã e preparação mental</strong></p><ul><li>Café da manhã leve (consulte o <a href="./education/nutrition/">Guia de Nutrição</a>)</li><li>Prática de atenção plena de 15 minutos</li><li>Reuniões de equipe</li></ul><p><strong>09:00-09:30 - Reunião Informativa sobre a Competição</strong></p><p><strong>Formato:</strong> Torneio de todos contra todos</p><ul><li>Equipes de 3</li><li>Jogar até 13 pontos</li><li>Todo mundo interpreta todo mundo</li><li>Concentre-se no PROCESSO, não no resultado</li></ul><p><strong>A reviravolta: Avaliação do desempenho mental</strong></p><div class="tip custom-block"><p class="custom-block-title">Sistema de Pontuação Dupla</p><p><strong>Tradicional:</strong> Pontos ganhos <strong>Desempenho Mental:</strong> Avaliado pelo MPC</p><p>Pontos de Desempenho Mental (0-5 por jogo):</p><ul><li>Ferramentas do Manual do Usuário Utilizadas</li><li>Apoiou os colegas de equipe de forma eficaz</li><li>Autocrítica controlada</li><li>Mantive-me presente (sem me apegar a fotos antigas)</li><li>Segurança psicológica comprovada</li></ul><p><strong>Vencedor:</strong> Melhor pontuação combinada (tradicional + mental)</p></div><p><strong>09:30-13:00 - Competição Matinal</strong></p><ul><li>Jogos de todos contra todos</li><li>O MPC observa e pontua</li><li>O treinador técnico fornece um breve feedback entre os jogos.</li><li>Pausas para hidratação e lanches</li></ul><p><strong>13:00-14:00 - Almoço</strong></p><ul><li>Focado em nutrição</li><li>Reflexão informal</li><li>Descansar</li></ul><p><strong>14:00-17:00 - Competição da tarde</strong></p><ul><li>Continuar o rodízio</li><li>Semifinais e finais</li><li>Aumento da pressão</li><li>Aplicar os conhecimentos da manhã</li></ul><p><strong>17:00-17:30 - Prêmios e Reconhecimento</strong></p><p><strong>Categorias:</strong></p><ul><li>Vencedor tradicional</li><li>Vencedor do desempenho mental</li><li>Maior melhoria</li><li>Melhor companheiro de equipe</li><li>Prêmio de Coragem (para os mais vulneráveis)</li></ul><p><strong>17:30-19:00 - Sessão de Reflexão Final</strong></p><p><strong>Fundamental:</strong> É aqui que a aprendizagem se consolida.</p><p><strong>Estrutura:</strong></p><p><strong>1. Reflexão Individual (15 min)</strong> Escreva no diário:</p><ul><li>O que você aprendeu sobre si mesmo neste fim de semana?</li><li>O que te surpreendeu?</li><li>O que você fará de diferente?</li><li>O que você vai levar para casa?</li></ul><p><strong>2. Partilha em Pequenos Grupos (30 min)</strong> Grupos de 4 a 5 pessoas:</p><ul><li>Compartilhar insights importantes</li><li>O que mais lhe chamou a atenção?</li><li>O que foi mais difícil?</li><li>O que era mais valioso?</li></ul><p><strong>3. Integração completa do grupo (30 min)</strong> Formem um círculo:</p><ul><li>Cada pessoa compartilha UMA principal conclusão</li><li>O MPC valida e conecta temas</li><li>Discuta: &quot;Como você aplicará isso?&quot;</li></ul><p><strong>4. Compromissos (15 min)</strong></p><ul><li>Cada pessoa declara um compromisso — &quot;Na minha próxima competição, eu irei...&quot;</li><li>Testemunhas e apoiadores do grupo</li></ul><p><strong>5. Encerramento (15 min)</strong></p><ul><li>Agradecemos a coragem dos participantes.</li><li>Lembrete sobre a confidencialidade</li><li>Trocar contatos</li><li>Planejar acompanhamento (sessão online opcional)</li></ul><p><strong>19:00 - Jantar e Partida</strong></p><h2 id="dicas-de-facilitacao" tabindex="-1">Dicas de Facilitação <a class="header-anchor" href="#dicas-de-facilitacao" aria-label="Permalink to &quot;Dicas de Facilitação&quot;">​</a></h2><h3 id="equilibrando-teoria-e-pratica" tabindex="-1">Equilibrando Teoria e Prática <a class="header-anchor" href="#equilibrando-teoria-e-pratica" aria-label="Permalink to &quot;Equilibrando Teoria e Prática&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Não sobrecarregue a teoria</p><p><strong>O erro:</strong> Falar demais e fazer de menos.</p><p><strong>O saldo:</strong></p><ul><li>A teoria gera consciência</li><li>A prática leva à perfeição</li><li>Integração de testes de competição</li><li>A reflexão consolida o aprendizado.</li></ul><p><strong>Regra geral:</strong> 30% teoria, 40% prática, 20% competição, 10% reflexão</p></div><h3 id="gerenciando-a-dinamica-de-grupo" tabindex="-1">Gerenciando a dinâmica de grupo <a class="header-anchor" href="#gerenciando-a-dinamica-de-grupo" aria-label="Permalink to &quot;Gerenciando a dinâmica de grupo&quot;">​</a></h3><p><strong>O Alfa Competitivo:</strong></p><ul><li>Quer vencer a qualquer custo</li><li>Resiste à vulnerabilidade</li><li><strong>Estratégia:</strong> Canalizar a competitividade para a pontuação do desempenho mental.</li></ul><p><strong>O Observador Silencioso:</strong></p><ul><li>Absorve tudo, não compartilha.</li><li><strong>Estratégia:</strong> Criar pontos de entrada de baixo risco, validar a observação como participação.</li></ul><p><strong>O Cético:</strong> — &quot;Essa coisa de ficar tocando em algo não funciona&quot;</p><ul><li><strong>Estratégia:</strong> Aikido Verbal - alinhar e pivotar (ver <a href="./workshop">Guia do Workshop</a>)</li></ul><p><strong>A pessoa que compartilha demais:</strong></p><ul><li>Domina a discussão</li><li><strong>Estratégia:</strong> &quot;Obrigado, vamos ouvir a opinião de outros&quot;</li></ul><h3 id="lidando-com-momentos-emocionais" tabindex="-1">Lidando com Momentos Emocionais <a class="header-anchor" href="#lidando-com-momentos-emocionais" aria-label="Permalink to &quot;Lidando com Momentos Emocionais&quot;">​</a></h3><p><strong>Alguém chora durante Fear in a Hat:</strong></p><ul><li>✅ Normalizar: &quot;Lágrimas são coragem, não fraqueza&quot;</li><li>✅ Ofereça lenços de papel, não tenha pressa</li><li>✅ Pergunte: &quot;Do que você precisa agora?&quot;</li><li>❌ Não diga: &quot;Está tudo bem, não chore&quot;</li></ul><p><strong>Conflito entre jogadores:</strong></p><ul><li>✅ Pausar e abordar</li><li>✅ &quot;O que está acontecendo agora?&quot;</li><li>✅ Use como momento de aprendizado</li><li>❌ Não ignore nem minimize</li></ul><p><strong>Alguém desliga:</strong></p><ul><li>✅ Faça o check-in em particular durante o intervalo</li><li>✅ &quot;Notei que você ficou quieto(a). O que houve?&quot;</li><li>✅ Ofereça opções: participe de forma diferente, faça uma pausa</li><li>❌ Não faça isso: Denuncie publicamente</li></ul><h2 id="acompanhamento-pos-acampamento" tabindex="-1">Acompanhamento pós-acampamento <a class="header-anchor" href="#acompanhamento-pos-acampamento" aria-label="Permalink to &quot;Acompanhamento pós-acampamento&quot;">​</a></h2><h3 id="imediato-24-48-horas" tabindex="-1">Imediato (24-48 horas) <a class="header-anchor" href="#imediato-24-48-horas" aria-label="Permalink to &quot;Imediato (24-48 horas)&quot;">​</a></h3><p><strong>Enviar a todos os participantes:</strong></p><ul><li>Mensagem de agradecimento Resumo dos principais pontos</li><li>Fotos do fim de semana</li><li>Lista de contatos (com permissão)</li><li>Link para recursos no site</li></ul><p><strong>Check-ins individuais:</strong></p><ul><li>Envie mensagem para qualquer pessoa que tenha compartilhado muito conteúdo. — Como você se sente em relação ao fim de semana?</li><li>Corrija qualquer resquício de vulnerabilidade.</li></ul><h3 id="curto-prazo-2-semanas" tabindex="-1">Curto prazo (2 semanas) <a class="header-anchor" href="#curto-prazo-2-semanas" aria-label="Permalink to &quot;Curto prazo (2 semanas)&quot;">​</a></h3><p><strong>Sessão online opcional (60-90 min):</strong></p><ul><li>Como você aplicou os aprendizados? O que está funcionando? Quais são os desafios?</li><li>Apoio entre pares e resolução de problemas</li><li>Reforçar os compromissos</li></ul><h3 id="longo-prazo-1-3-meses" tabindex="-1">Longo prazo (1-3 meses) <a class="header-anchor" href="#longo-prazo-1-3-meses" aria-label="Permalink to &quot;Longo prazo (1-3 meses)&quot;">​</a></h3><p><strong>Participantes da pesquisa:</strong></p><ul><li>O que há de diferente no seu jogo?</li><li>Quais ferramentas você ainda está usando?</li><li>O que tornaria o próximo acampamento melhor? Você recomendaria para outras pessoas?</li></ul><p><strong>Impacto na pista:</strong></p><ul><li>Resultados da competição</li><li>Autoconfiança relatada</li><li>Dinâmica de equipe</li><li>Engajamento contínuo</li></ul><h2 id="adaptacao-para-diferentes-tamanhos-de-grupo" tabindex="-1">Adaptação para diferentes tamanhos de grupo <a class="header-anchor" href="#adaptacao-para-diferentes-tamanhos-de-grupo" aria-label="Permalink to &quot;Adaptação para diferentes tamanhos de grupo&quot;">​</a></h2><h3 id="acampamento-pequeno-10-12-jogadores" tabindex="-1">Acampamento pequeno (10-12 jogadores) <a class="header-anchor" href="#acampamento-pequeno-10-12-jogadores" aria-label="Permalink to &quot;Acampamento pequeno (10-12 jogadores)&quot;">​</a></h3><p><strong>Vantagens:</strong></p><ul><li>Compartilhamento mais profundo</li><li>Maior atenção individualizada</li><li>Laços mais fortes</li></ul><p><strong>Ajustes:</strong></p><ul><li>Teoria de grupo único para todo o grupo</li><li>Mais tempo por pessoa nas atividades</li><li>Formato de competição intimista</li></ul><h3 id="acampamento-grande-16-20-jogadores" tabindex="-1">Acampamento grande (16-20 jogadores) <a class="header-anchor" href="#acampamento-grande-16-20-jogadores" aria-label="Permalink to &quot;Acampamento grande (16-20 jogadores)&quot;">​</a></h3><p><strong>Vantagens:</strong></p><ul><li>Diversas perspectivas</li><li>Maior variedade de competições</li><li>Economias de escala</li></ul><p><strong>Ajustes:</strong></p><ul><li>Dividir em 2 grupos para algumas sessões teóricas.</li><li>Necessita-se de 2 MPC/facilitadores</li><li>Tabela de torneio maior</li><li>Rotações mais estruturadas</li></ul><h2 id="consideracoes-sobre-o-orcamento" tabindex="-1">Considerações sobre o orçamento <a class="header-anchor" href="#consideracoes-sobre-o-orcamento" aria-label="Permalink to &quot;Considerações sobre o orçamento&quot;">​</a></h2><h3 id="receita" tabindex="-1">Receita <a class="header-anchor" href="#receita" aria-label="Permalink to &quot;Receita&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Preço por pessoa</th><th>20 pessoas</th><th>10 pessoas</th></tr></thead><tbody><tr><td><strong>Inscrição</strong></td><td>€150-250</td><td>€3.000-5.000</td><td>€1.500-2.500</td></tr></tbody></table><h3 id="despesas" tabindex="-1">Despesas <a class="header-anchor" href="#despesas" aria-label="Permalink to &quot;Despesas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Categoria</th><th>Custo</th><th>Observações</th></tr></thead><tbody><tr><td><strong>Aluguel do espaço</strong></td><td>€500-1.000</td><td>Tarifa de fim de semana</td></tr><tr><td><strong>Acomodação</strong></td><td>€40-60/pessoa/noite</td><td>Quartos compartilhados</td></tr><tr><td><strong>Refeições</strong></td><td>€30-40/pessoa/dia</td><td>6 refeições</td></tr><tr><td><strong>Equipe</strong></td><td>€500-1.000</td><td>MPC + treinadores</td></tr><tr><td><strong>Materiais</strong></td><td>€100-200</td><td>Folhas de exercícios, materiais</td></tr><tr><td><strong>Prêmios</strong></td><td>€100-200</td><td>Itens de reconhecimento</td></tr></tbody></table><p><strong>Total por pessoa:</strong> €120-180 <strong>Margem de lucro:</strong> €30-70 por pessoa (ou ponto de equilíbrio para atividades de integração comunitária)</p><h2 id="metricas-de-sucesso" tabindex="-1">Métricas de Sucesso <a class="header-anchor" href="#metricas-de-sucesso" aria-label="Permalink to &quot;Métricas de Sucesso&quot;">​</a></h2><h3 id="indicadores-imediatos" tabindex="-1">Indicadores Imediatos <a class="header-anchor" href="#indicadores-imediatos" aria-label="Permalink to &quot;Indicadores Imediatos&quot;">​</a></h3><ul><li>[ ] Pontuação de segurança psicológica (média de 1 a 10 &gt;7)</li><li>[ ] Taxa de participação (&gt;80% de compartilhamento ativo)</li><li>[ ] Taxa de conclusão (&gt;90% de permanência durante todo o fim de semana)</li><li>[ ] Pontuação de satisfação (média de 1 a 10 &gt; 8)</li></ul><h3 id="indicadores-de-longo-prazo" tabindex="-1">Indicadores de longo prazo <a class="header-anchor" href="#indicadores-de-longo-prazo" aria-label="Permalink to &quot;Indicadores de longo prazo&quot;">​</a></h3><ul><li>[ ] Mudança de comportamento (uso de ferramentas na competição)</li><li>[ ] Melhoria de desempenho (autoavaliada)</li><li>[ ] Construção de comunidade (manter contato)</li><li>[ ] Indicações (recomendar a outros)</li></ul><h2 id="erros-comuns-a-evitar" tabindex="-1">Erros comuns a evitar <a class="header-anchor" href="#erros-comuns-a-evitar" aria-label="Permalink to &quot;Erros comuns a evitar&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Armadilhas</p><p><strong>1. Conteúdo em excesso</strong></p><ul><li>Tentando abranger tudo</li><li><strong>Correção:</strong> Foque na profundidade, não na amplitude</li></ul><p><strong>2. Ignorar a reflexão</strong></p><ul><li>Correndo para a próxima atividade</li><li><strong>Correção:</strong> Tempo de processamento incluído</li></ul><p><strong>3. Ignorar a resistência</strong></p><ul><li>Superando o ceticismo <strong>Solução:</strong> Aborde o problema diretamente com Aikido Verbal.</li></ul><p><strong>4. Acompanhamento técnico durante a aula teórica</strong></p><ul><li>Misturando papéis</li><li><strong>Correção:</strong> Definir claramente os limites entre o MPC e o treinador técnico.</li></ul><p><strong>5. Sem acompanhamento</strong></p><ul><li>O fim de semana acaba, o aprendizado para.</li><li><strong>Correção:</strong> Planejar pontos de contato pós-acampamento</li></ul></div><h2 id="recursos" tabindex="-1">Recursos <a class="header-anchor" href="#recursos" aria-label="Permalink to &quot;Recursos&quot;">​</a></h2><h3 id="deste-site" tabindex="-1">Deste Site <a class="header-anchor" href="#deste-site" aria-label="Permalink to &quot;Deste Site&quot;">​</a></h3><ul><li><a href="./workshop">Guia do Workshop</a> - Protocolos de facilitação detalhados</li><li><a href="./training-session">Guia da Sessão de Treinamento</a> - Para prática contínua</li><li><a href="./education/nutrition/">Nutrição</a> - Protocolos para o dia da competição</li><li><a href="./education/mental-strength/">Força Mental</a> - Conceitos de jogo interior</li><li><a href="./education/mindfulness/">Mindfulness</a> - Técnicas de presença</li><li><a href="./education/tactics/">Táticas</a> - Pensamento estratégico</li></ul><h3 id="leitura-recomendada" tabindex="-1">Leitura recomendada <a class="header-anchor" href="#leitura-recomendada" aria-label="Permalink to &quot;Leitura recomendada&quot;">​</a></h3><ul><li><em>O Jogo Interior do Tênis</em> por Timothy Gallwey</li><li><em>Mentalidade</em> por Carol Dweck</li><li><em>A Organização Destemida</em> por Amy Edmondson</li></ul>',135))])}]]);export{p as __pageData,c as default};
